2641	  }
2642	
2643	  if (C.getArgs().hasArg(options::OPT_print_search_dirs)) {
2644	    llvm::outs() << "programs: =";
2645	    bool separator = false;
2646	    // Print -B and COMPILER_PATH.
2647	    for (const std::string &Path : PrefixDirs) {
