1727	    StringRef TripleObjectFormat =
1728	        Triple.getObjectFormatTypeName(Triple.getObjectFormat());
1729	    if (Triple.getEnvironmentVersion().empty() && TripleVersionName != "" &&
1730	        TripleVersionName != TripleObjectFormat) {
