5571	      std::optional<llvm::sys::ProcessStatistics> ProcStat =
5572	          Cmd.getProcessStatistics();
5573	      if (!ProcStat)
5574	        return;
5575	
5890	
5891	    // Get compiler tool.
5892	    const Tool *T = TC.SelectTool(*CJ);
5893	    if (!T)
